 ROOT.mkdir(parents=True,exist_ok=True);report=load(OLD/'report.json');ledger=load(REPO/'artifacts/memory-reuse-loop-20261026/attempts.json');xs=[a for a in ledger if a.get('channel')=='project_task_work_v1'];full=report['by_choice']['full'];baseline=full['baseline'];total=full['reuse'];failed=next(a for a in xs if a.get('failure_reason')=='root_uses_missing');extra={k:total[k]-baseline[k] for k in ['total_tokens','machine_ms','api_equivalent_usd']};waste={'total_tokens':failed['total_tokens'],'machine_ms':failed['total_ms'],'api_equivalent_usd':failed['api_equivalent_usd']};left={k:extra[k]-waste[k] for k in extra}
